head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setColumnChooseOption]<br/>Body Column 정보를 사용하여 특정 Column 에 '선택 안내'를 의미하는 아이템을 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 chooseOption 속성을 설정하려는 Body Column 의 인덱스를 설정할 수 있어야 합니다.",
        "columnInfo(필수) 파라미터의 Column 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.",
        "Body Column 이 inputType='select' 인 경우에 동작합니다.",
        "메소드가 정상적으로 실행되면 Column 의 chooseOption 속성은 true 로 강제 설정됩니다.",
        "chooseOptionValue(필수) 파라미터로 '선택 안내' 아이템의 Value 값을 설정합니다.",
        "chooseOptionLabel(필수) 파라미터로 '선택 안내' 아이템의 Label 값을 설정합니다.",
        "chooseOptionLabel(필수) 파라미터값은 첫번째 아이템으로 표시되며 Column 의 chooseOptionLabel 속성에 설정됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof dlt_grade !== 'undefined') {
        $p.data.remove("dlt_grade");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Column 인덱스 - 0:name(text) / 1:memo(text, 숨김 setColumnVisible(1,false)) / 2:grade(select, DataList dlt_grade 바인딩) / 3:qty(number, 비-select). 숨김 컬럼 포함 인덱스. 데이터 Row 4개.\n[절차] columnInfo(인덱스) / chooseOptionValue / chooseOptionLabel 선택 후 (setColumnChooseOption 실행) -> 해당 select 컬럼 첫 아이템으로 선택 안내 아이템 설정.\n[확인] select 컬럼(인덱스2) 은 chooseOption=true 적용 + 첫 아이템 label/value 가 입력값과 일치. 비-select 컬럼(인덱스3) 은 미동작. 모두 반환영역에 출력됨."', '', 'label1');

    // select 컬럼 옵션용 DataList (label/value) 동적 생성
    let strGrade = '';
    strGrade += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_grade" baseNode="list" repeatNode="map">';
    strGrade += '<w2:columnInfo>';
    strGrade += '<w2:column id="label" name="label" dataType="text"></w2:column>';
    strGrade += '<w2:column id="value" name="value" dataType="text"></w2:column>';
    strGrade += '</w2:columnInfo>';
    strGrade += '<w2:data use="true"></w2:data>';
    strGrade += '</w2:dataList>';
    $p.data.create(strGrade);
    dlt_grade.setJSON([
        { "label": "A등급", "value": "A" },
        { "label": "B등급", "value": "B" },
        { "label": "C등급", "value": "C" }
    ], false);

    // GridView 와 바인딩할 body DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="memo" name="memo" dataType="text"></w2:column>';
    strDlt += '<w2:column id="grade" name="grade" dataType="text"></w2:column>';
    strDlt += '<w2:column id="qty" name="qty" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "name": "노트북", "memo": "재고", "grade": "A", "qty": 3 },
        { "name": "모니터", "memo": "재고", "grade": "B", "qty": 5 },
        { "name": "키보드", "memo": "재고", "grade": "C", "qty": 7 },
        { "name": "마우스", "memo": "재고", "grade": "A", "qty": 9 }
    ], false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
        editable: "true"
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (Header 4컬럼 + gBody, index2 는 select 컬럼)
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:600px;height:240px;">';
    strTarget += '<w2:caption style="" id="caption1" value="setColumnChooseOption 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="hcol1" value="품목"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol2" value="메모(숨김)"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="hcol3" value="등급(select)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol4" value="수량(비-select)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    // index 0 : name (text)
    strTarget += '<w2:column width="140" style="" inputType="text" id="name" dataList="name"></w2:column>';
    // index 1 : memo (text) - setColumnVisible(1,false) 로 숨김 -> 숨김 포함 인덱스 검증용
    strTarget += '<w2:column width="120" style="" inputType="text" id="memo" dataList="memo"></w2:column>';
    // index 2 : grade (select) - DataList(dlt_grade) 바인딩 itemset -> setColumnChooseOption 대상
    strTarget += '<w2:column width="160" style="" inputType="select" id="grade" dataList="grade">';
    strTarget += '<w2:choices><w2:itemset nodeset="data:dlt_grade"><w2:label ref="label"></w2:label><w2:value ref="value"></w2:value></w2:itemset></w2:choices>';
    strTarget += '</w2:column>';
    // index 3 : qty (number) - 비-select 컬럼 -> setColumnChooseOption 미동작 검증용
    strTarget += '<w2:column width="*" style="" inputType="text" dataType="number" id="qty" dataList="qty"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 두번째 Column(memo, 인덱스 1) 숨김 -> 숨김 Column 포함 인덱스 검증용
    target1.setColumnVisible(1, false);
}



// chooseOption 적용 상태를 읽어 반환 문자열로 만든다.
//  cellInfo.options 의 chooseOption / chooseOptionValue / chooseOptionLabel 로 확인.
scwin.readChooseInfo = function (colIndex) {
    let ci = target1.getCellInfo(colIndex);
    let opt = (ci && ci.options) ? ci.options : {};
    return "[인덱스 " + colIndex + " / " + target1.getColumnID(colIndex) + "] inputType=" + opt.inputType
        + " | chooseOption=" + opt.chooseOption
        + " | chooseOptionValue='" + (opt.chooseOptionValue == null ? "" : opt.chooseOptionValue) + "'"
        + " | chooseOptionLabel='" + (opt.chooseOptionLabel == null ? "" : opt.chooseOptionLabel) + "'";
}

// [실행] setColumnChooseOption : select 컬럼 첫 아이템으로 선택 안내 아이템을 설정한다.
//  columnInfo(인덱스) / chooseOptionValue / chooseOptionLabel 파라미터를 그대로 전달.
//  select 컬럼이면 편집모드로 렌더된 첫 아이템(itemArr[0]) 을 읽어 'chooseOptionLabel 이 첫번째 아이템으로 표시' 도 함께 확인.
scwin.btn_setChooseOption_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());
    let chooseValue = par_chooseOptionValue.getValue();
    let chooseLabel = par_chooseOptionLabel.getValue();

    target1.setColumnChooseOption(columnInfo, chooseValue, chooseLabel);

    let msg = "setColumnChooseOption(" + columnInfo + ", '" + chooseValue + "', '" + chooseLabel + "') 실행 -> " + scwin.readChooseInfo(columnInfo);

    // select 컬럼이면 렌더된 첫 아이템(itemArr[0]) 확인 -> chooseOptionLabel 이 첫번째 아이템으로 표시되는지
    //  (WebSquare select 셀은 native select 가 아닌 w2selectbox 로 렌더 -> cellInfo.select.itemArr 로 확인)
    if (target1.getCellInfo(columnInfo).options.inputType === "select") {
        let td = document.querySelector("td[id*='target1_cell_0_" + columnInfo + "']");
        target1.setEditMode(td);
        let sel = target1.getCellInfo(columnInfo).select;
        if (sel && sel.itemArr && sel.itemArr.length > 0) {
            msg += "\n[첫 아이템] label='" + sel.itemArr[0].label + "' value='" + sel.itemArr[0].value;
        }
    }
    wf_body_bottom.getObj("scwin").setReturnValue(msg);
}
